// src/AudioFileList.js
import React, { useEffect, useState } from 'react';

function AudioFileList() {
    const [audioFiles, setAudioFiles] = useState([]);
    const [audioSrc, setAudioSrc] = useState(null); // 用於播放音檔
    const [ws, setWs] = useState(null); // WebSocket 連接

    useEffect(() => {
        // 建立 WebSocket 連接
        const websocket = new WebSocket('ws://localhost:8000');
        setWs(websocket);

        websocket.onopen = () => {
            console.log('Connected to WebSocket server');
        };

        websocket.onmessage = (event) => {
            const data = JSON.parse(event.data);

            if (data.audioData) {
                // 如果收到的是音檔數據，解碼並設置為播放來源
                const binaryString = atob(data.audioData);
                const bytes = Uint8Array.from(binaryString, char => char.charCodeAt(0));
                const audioBlob = new Blob([bytes], { type: 'audio/wav' });
                const audioUrl = URL.createObjectURL(audioBlob);
                setAudioSrc(audioUrl);
            } else if (Array.isArray(data)) {
                setAudioFiles(data); // 更新音檔列表
            } else if (data.error) {
                console.error(data.error);
                alert(data.error); // 顯示錯誤信息
            }
        };

        websocket.onclose = () => {
            console.log('WebSocket connection closed');
        };

        websocket.onerror = (error) => {
            console.log('WebSocket error:', error);
        };

        // 清理 WebSocket 連接
        return () => {
            websocket.close();
        };
    }, []);

    // 請求指定音檔的函數
    const requestFile = (filename) => {
        if (ws && ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ request_file: filename }));
            console.log(`Requested file: ${filename}`);
        } else {
            console.log('WebSocket is not open');
        }
    };

    return (
        <div>
            <h2>Audio Files in Folder</h2>
            <ul>
                {audioFiles.map((file, index) => (
                    <li key={index}>
                        {file} <button onClick={() => requestFile(file)}>Play</button>
                    </li>
                ))}
            </ul>

            {audioSrc && (
                <div>
                    <h3>Playing Audio</h3>
                    <audio controls src={audioSrc}></audio>
                </div>
            )}
        </div>
    );
}

export default AudioFileList;
